package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_reference_check") public class ReferenceCheck extends RspAuditedEntity{
 public enum Outcome{PENDING,SATISFACTORY,CONCERN,INCONCLUSIVE,NOT_APPLICABLE}public enum Status{DRAFT,COMPLETED,VALIDATED}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="stage_id",nullable=false,length=36)private String stageId;@Column(name="check_type",nullable=false,length=80)private String checkType;@Column(name="source_category",nullable=false,length=100)private String sourceCategory;@Column(name="lawful_basis_reference",nullable=false,length=500)private String lawfulBasisReference;@Column(name="requested_at",nullable=false)private Instant requestedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="checker_employee_no",nullable=false,length=100)private String checkerEmployeeNo;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(name="applicant_safe_text",length=1000)private String applicantSafeText;@Column(name="confidential_notes",length=4000)private String confidentialNotes;@Column(name="validated_by",length=100)private String validatedBy;@Column(name="validated_at")private Instant validatedAt;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;
 protected ReferenceCheck(){}public ReferenceCheck(String agency,String proceeding,String candidate,String stage,String type,String source,String basis,String checker,Instant at){super(agency);proceedingId=requiredText(proceeding,"proceedingId");candidateId=requiredText(candidate,"candidateId");stageId=requiredText(stage,"stageId");checkType=requiredText(type,"checkType");sourceCategory=requiredText(source,"sourceCategory");lawfulBasisReference=requiredText(basis,"lawfulBasisReference");checkerEmployeeNo=requiredText(checker,"checkerEmployeeNo");requestedAt=Objects.requireNonNull(at);outcome=Outcome.PENDING;status=Status.DRAFT;}
 public void complete(Outcome result,String safe,String confidential,String actor,Instant at){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a DRAFT reference check may be completed");if(!checkerEmployeeNo.equalsIgnoreCase(requiredText(actor,"actor")))throw new IllegalLifecycleTransitionException("Only the assigned checker may complete this check");if(result==Outcome.PENDING)throw new IllegalArgumentException("A completed outcome is required");outcome=Objects.requireNonNull(result);applicantSafeText=optionalText(safe);confidentialNotes=optionalText(confidential);completedAt=Objects.requireNonNull(at);status=Status.COMPLETED;}
 public void validate(String actor,Instant at){if(status!=Status.COMPLETED)throw new IllegalLifecycleTransitionException("Only a COMPLETED check may be validated");String validator=requiredText(actor,"actor");if(checkerEmployeeNo.equalsIgnoreCase(validator))throw new IllegalLifecycleTransitionException("The checker cannot validate their own check");validatedBy=validator;validatedAt=Objects.requireNonNull(at);status=Status.VALIDATED;}
 public String getProceedingId(){return proceedingId;}public String getCandidateId(){return candidateId;}public String getStageId(){return stageId;}public String getCheckType(){return checkType;}public String getSourceCategory(){return sourceCategory;}public String getLawfulBasisReference(){return lawfulBasisReference;}public String getCheckerEmployeeNo(){return checkerEmployeeNo;}public Outcome getOutcome(){return outcome;}public String getApplicantSafeText(){return applicantSafeText;}public String getConfidentialNotes(){return confidentialNotes;}public Status getStatus(){return status;}public String getValidatedBy(){return validatedBy;}
}
